-- strategy tables, generated by analysis/db_dump.py. Idempotent.
create table if not exists watch_wallets (
  wallet text primary key, tag text not null, action text not null,
  trades int, gross_sol double precision, net_est double precision,
  per_trade double precision, win double precision,
  size_med double precision, rank_med double precision,
  hold_med double precision, devs int, days_active int, pos_days int,
  first_day date, last_day date, built_from text,
  updated_at timestamptz default now());
create index if not exists watch_wallets_action on watch_wallets(action);
create table if not exists dev_history (
  dev text primary key, launches int, first_seen date, last_seen date,
  updated_at timestamptz default now());
begin;
delete from watch_wallets;
commit;
